  "templatePickerSubtitle": <String, String>{"en": "They insert an editable outline. Photos, voice, sketches, tags and people remain available as usual.", "it": "Inseriscono una traccia modificabile. Foto, voce, sketch, tag e persone restano disponibili normalmente.", "es": "Insertan una guía editable. Fotos, voz, bocetos, etiquetas y personas siguen disponibles con normalidad.", "fr": "Ils insèrent une trame modifiable. Photos, voix, croquis, tags et personnes restent disponibles normalement.", "pt": "Inserem um guia editável. Fotos, voz, esboços, etiquetas e pessoas continuam disponíveis normalmente."},
  "templateMorningTitle": <String, String>{"en": "Morning", "it": "Mattino", "es": "Mañana", "fr": "Matin", "pt": "Manhã"},
  "templateMorningDesc": <String, String>{"en": "Intention, energy and priority for the day.", "it": "Intenzione, energia e priorità della giornata.", "es": "Intención, energía y prioridad del día.", "fr": "Intention, énergie et priorité de la journée.", "pt": "Intenção, energia e prioridade do dia."},
  "templateMorningSeed": <String, String>{"en": "Morning routine\n\n☐ How do I feel right now?\n☐ What do I want to protect today?\n☐ The most important thing to do\n☐ One kind gesture toward myself\n\nFree space:", "it": "Routine del mattino\n\n☐ Come mi sento adesso?\n☐ Cosa voglio proteggere oggi?\n☐ La cosa più importante da fare\n☐ Un gesto gentile verso di me\n\nSpazio libero:", "es": "Rutina de la mañana\n\n☐ ¿Cómo me siento ahora?\n☐ ¿Qué quiero proteger hoy?\n☐ Lo más importante que tengo que hacer\n☐ Un gesto amable conmigo\n\nEspacio libre:", "fr": "Routine du matin\n\n☐ Comment est-ce que je me sens maintenant ?\n☐ Qu’est-ce que je veux protéger aujourd’hui ?\n☐ La chose la plus importante à faire\n☐ Un geste bienveillant envers moi-même\n\nEspace libre :", "pt": "Rotina da manhã\n\n☐ Como me sinto agora?\n☐ O que quero proteger hoje?\n☐ A coisa mais importante a fazer\n☐ Um gesto gentil comigo\n\nEspaço livre:"},
  "templateEveningTitle": <String, String>{"en": "Evening", "it": "Sera", "es": "Noche", "fr": "Soir", "pt": "Noite"},
  "templateEveningDesc": <String, String>{"en": "Close the day and let go of what you do not need.", "it": "Chiudi la giornata e lascia andare ciò che non serve.", "es": "Cierra el día y deja ir lo que no necesitas.", "fr": "Termine la journée et laisse partir ce qui ne sert plus.", "pt": "Fecha o dia e deixa ir o que não precisas."},
  "templateEveningSeed": <String, String>{"en": "Evening routine\n\n☐ The best thing about today\n☐ What made me tired?\n☐ What did I learn?\n☐ What do I want to remember tomorrow?\n\nFinal thought:", "it": "Routine della sera\n\n☐ La cosa migliore di oggi\n☐ Cosa mi ha stancato?\n☐ Cosa ho imparato?\n☐ Cosa voglio ricordare domani?\n\nPensiero finale:", "es": "Rutina de la noche\n\n☐ Lo mejor de hoy\n☐ ¿Qué me cansó?\n☐ ¿Qué aprendí?\n☐ ¿Qué quiero recordar mañana?\n\nPensamiento final:", "fr": "Routine du soir\n\n☐ La meilleure chose d’aujourd’hui\n☐ Qu’est-ce qui m’a fatigué ?\n☐ Qu’est-ce que j’ai appris ?\n☐ Qu’est-ce que je veux retenir demain ?\n\nPensée finale :", "pt": "Rotina da noite\n\n☐ A melhor coisa de hoje\n☐ O que me cansou?\n☐ O que aprendi?\n☐ O que quero recordar amanhã?\n\nPensamento final:"},
  "templateGratitudeTitle": <String, String>{"en": "Gratitude", "it": "Gratitudine", "es": "Gratitud", "fr": "Gratitude", "pt": "Gratidão"},
  "templateGratitudeDesc": <String, String>{"en": "Three concrete things to keep from the day.", "it": "Tre cose concrete da conservare della giornata.", "es": "Tres cosas concretas que conservar del día.", "fr": "Trois choses concrètes à garder de la journée.", "pt": "Três coisas concretas para guardar do dia."},
  "templateGratitudeSeed": <String, String>{"en": "Gratitude\n\n♡ 1. \n♡ 2. \n♡ 3. \n\nWhy one of these things mattered to me:", "it": "Gratitudine\n\n♡ 1. \n♡ 2. \n♡ 3. \n\nPerché una di queste cose è stata importante per me:", "es": "Gratitud\n\n♡ 1. \n♡ 2. \n♡ 3. \n\nPor qué una de estas cosas fue importante para mí:", "fr": "Gratitude\n\n♡ 1. \n♡ 2. \n♡ 3. \n\nPourquoi l’une de ces choses a compté pour moi :", "pt": "Gratidão\n\n♡ 1. \n♡ 2. \n♡ 3. \n\nPorque uma destas coisas foi importante para mim:"},
  "templateTravelTitle": <String, String>{"en": "Travel", "it": "Viaggio", "es": "Viaje", "fr": "Voyage", "pt": "Viagem"},
  "templateTravelDesc": <String, String>{"en": "Places, moments, details and memories not to lose.", "it": "Luoghi, momenti, dettagli e ricordi da non perdere.", "es": "Lugares, momentos, detalles y recuerdos que no quieres perder.", "fr": "Lieux, moments, détails et souvenirs à ne pas perdre.", "pt": "Locais, momentos, detalhes e memórias a não perder."},
  "templateTravelSeed": <String, String>{"en": "Travel diary\n\n☐ Where did I go?\n☐ The best moment\n☐ Something that surprised me\n☐ A place or flavor to remember\n☐ What would I do again tomorrow?\n\nNotes:", "it": "Diario di viaggio\n\n☐ Dove sono stato/a?\n☐ Il momento più bello\n☐ Una cosa che mi ha sorpreso\n☐ Un posto o sapore da ricordare\n☐ Cosa rifarei domani?\n\nAppunti:", "es": "Diario de viaje\n\n☐ ¿Dónde estuve?\n☐ El mejor momento\n☐ Algo que me sorprendió\n☐ Un lugar o sabor que recordar\n☐ ¿Qué repetiría mañana?\n\nNotas:", "fr": "Journal de voyage\n\n☐ Où suis-je allé(e) ?\n☐ Le meilleur moment\n☐ Quelque chose qui m’a surpris(e)\n☐ Un lieu ou une saveur à retenir\n☐ Qu’est-ce que je referais demain ?\n\nNotes :", "pt": "Diário de viagem\n\n☐ Onde estive?\n☐ O melhor momento\n☐ Algo que me surpreendeu\n☐ Um local ou sabor para recordar\n☐ O que faria de novo amanhã?\n\nNotas:"},
  "templateTravelMedia": <String, String>{"en": "Add photos or a voice note to complete the memory.", "it": "Aggiungi foto o una nota vocale per completare il ricordo.", "es": "Añade fotos o una nota de voz para completar el recuerdo.", "fr": "Ajoute des photos ou une note vocale pour compléter le souvenir.", "pt": "Adiciona fotos ou uma nota de voz para completar a memória."},
  "templateSpecialTitle": <String, String>{"en": "Special day", "it": "Giorno speciale", "es": "Día especial", "fr": "Journée spéciale", "pt": "Dia especial"},
  "templateSpecialDesc": <String, String>{"en": "For birthdays, anniversaries and important days.", "it": "Per compleanni, anniversari e giornate importanti.", "es": "Para cumpleaños, aniversarios y días importantes.", "fr": "Pour les anniversaires et les journées importantes.", "pt": "Para aniversários e dias importantes."},
  "templateSpecialSeed": <String, String>{"en": "Special day\n\n☐ Why is today important?\n☐ Who was I with?\n☐ The moment I want to remember\n☐ A phrase or detail to keep\n\nHow I felt:", "it": "Giorno speciale\n\n☐ Perché oggi è importante?\n☐ Con chi ero?\n☐ Il momento che voglio ricordare\n☐ Una frase o un dettaglio da conservare\n\nCome mi sono sentito/a:", "es": "Día especial\n\n☐ ¿Por qué es importante hoy?\n☐ ¿Con quién estaba?\n☐ El momento que quiero recordar\n☐ Una frase o detalle que conservar\n\nCómo me sentí:", "fr": "Journée spéciale\n\n☐ Pourquoi aujourd’hui est-il important ?\n☐ Avec qui étais-je ?\n☐ Le moment que je veux retenir\n☐ Une phrase ou un détail à garder\n\nComment je me suis senti(e) :", "pt": "Dia especial\n\n☐ Porque é que hoje é importante?\n☐ Com quem estava?\n☐ O momento que quero recordar\n☐ Uma frase ou detalhe para guardar\n\nComo me senti:"},
  "templateSpecialMedia": <String, String>{"en": "Photos and voice remain available in the same diary.", "it": "Foto e voce restano disponibili nello stesso diario.", "es": "Fotos y voz siguen disponibles en el mismo diario.", "fr": "Photos et voix restent disponibles dans le même journal.", "pt": "Fotos e voz continuam disponíveis no mesmo diário."},
  "templateReflectionTitle": <String, String>{"en": "Reflection", "it": "Riflessione", "es": "Reflexión", "fr": "Réflexion", "pt": "Reflexão"},
  "templateReflectionDesc": <String, String>{"en": "A deeper space to put your thoughts in order.", "it": "Uno spazio più profondo per mettere ordine nei pensieri.", "es": "Un espacio más profundo para ordenar tus pensamientos.", "fr": "Un espace plus profond pour mettre tes pensées en ordre.", "pt": "Um espaço mais profundo para organizar os pensamentos."},
  "templateReflectionSeed": <String, String>{"en": "Reflection\n\nWhat happened?\n\nWhat did I feel?\n\nWhat did I need?\n\nWhat can I carry with me from this experience?\n\nOne small concrete step:", "it": "Riflessione\n\nCosa è successo?\n\nCosa ho provato?\n\nDi cosa avevo bisogno?\n\nCosa posso portare con me da questa esperienza?\n\nUn piccolo passo concreto:", "es": "Reflexión\n\n¿Qué pasó?\n\n¿Qué sentí?\n\n¿Qué necesitaba?\n\n¿Qué puedo llevarme de esta experiencia?\n\nUn pequeño paso concreto:", "fr": "Réflexion\n\nQue s’est-il passé ?\n\nQu’ai-je ressenti ?\n\nDe quoi avais-je besoin ?\n\nQue puis-je garder de cette expérience ?\n\nUn petit pas concret :", "pt": "Reflexão\n\nO que aconteceu?\n\nO que senti?\n\nDo que precisava?\n\nO que posso levar comigo desta experiência?\n\nUm pequeno passo concreto:"},
